{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Health care workers (HCWs) are more than ten times more likely to contract COVID-19 than the general population, thus demonstrating the burden of COVID-19 among HCWs [11]. Factors that expose HCWs to a differentially high-risk of COVID-19 acquisition are important to elucidate, enable appropriate public health interventions to mitigate against high risk and reduce adverse outcomes from the infection.",
      "reason": "The evidence describes the burden and the importance of identifying risk factors, but it does not clearly describe the current state of knowledge with specific important uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "evidence base to accurately and timely guide effective clinical and public health interventions.",
      "reason": "The rationale for doing the review is explained as providing an evidence base to guide interventions."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "In a previous systematic review, Gomez-Ochoa et al revealed the lack of PPE, patient contact, and suboptimal hand hygiene as risk factors for COVID-19 among HCWs [12]. However, no meta-analysis was conducted. Furthermore, Chou et al, living rapid review focused on a broad range of coronavirus infections. Of the 64 studies that met inclusion criteria, 43 studies addressed the burden of HCW infections (15 on SARS-CoV2) and 34 studies addressed risk factors (3 on SARS-CoV-2) [13]. Only 3 studies included reported risk factors for SARS-CoV-2 infections among health workers.",
      "reason": "The evidence cites earlier reviews and indicates gaps (e.g., no meta-analysis in the prior systematic review; limited coverage of SARS-CoV-2 risk factors). However, it does not clearly explain the need specifically as an update/replication of similar reviews in a way that identifies the current review as an update."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The available evidence describes a systematic review/meta-analysis of risk factors and does not describe an intervention effect or a proposed mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The available evidence does not indicate an intervention or complex intervention delivery context for which a logic model would be considered."
    }
  ],
  "confidence": 62
}

